 $('forward').innerHTML=[['September carryover',forward.carryoverJobIds.length],['Committed scheduled',forward.committedScheduled.length],['Modeled new intake',forward.modeledNewIntake],['Modeled completion capacity',forward.modeledCompletionCapacity]].map(x=>'<div class="metric"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');
